```javascript
async function hentLand(navn) {
  try {
    const response = await fetch(
      "https://restcountries.com/v3.1/name/" + navn
    );

    if (!response.ok) {
      throw new Error("Fant ikke landet: " + navn);
    }

    const data = await response.json();
    const land = data[0];

    console.log("Land:", land.name.official);
    console.log("Befolkning:", land.population.toLocaleString());

  } catch (error) {
    console.error("Feil:", error.message);
  }
}

hentLand("norway");
// Land: Kingdom of Norway
// Befolkning: 5,379,475
```

Funksjonen brukar async/await for lesbar asynkron kode. fetch() sender ein GET-førespurnad til API-et. Vi sjekkar response.ok for å fange HTTP-feil, parsar JSON-svaret, og hentar ut relevant data. try/catch sikrar at feil vert handterte gracefully.

```javascript
async function visBrukere() {
  const container = document.querySelector("#brukere");
  container.textContent = "Laster...";

  try {
    const response = await fetch(
      "https://jsonplaceholder.typicode.com/users"
    );

    if (!response.ok) {
      throw new Error("Serverfeil: " + response.status);
    }

    const brukere = await response.json();
    container.innerHTML = "";

    brukere.forEach(bruker => {
      const kort = document.createElement("div");
      kort.classList.add("bruker-kort");

      const navn = document.createElement("h3");
      navn.textContent = bruker.name;

      const epost = document.createElement("p");
      epost.textContent = "E-post: " + bruker.email;

      const firma = document.createElement("p");
      firma.textContent = "Firma: " + bruker.company.name;

      kort.appendChild(navn);
      kort.appendChild(epost);
      kort.appendChild(firma);
      container.appendChild(kort);
    });

  } catch (error) {
    container.textContent = "Feil: " + error.message;
    container.style.color = "red";
  }
}

visBrukere();
```

Funksjonen kombinerer async/await (for asynkron datahenting), try/catch (for feilhandtering), fetch og response.json() (for API-kommunikasjon), og createElement/appendChild (for DOM-manipulering). Brukaren ser "Laster..." medan data vert henta, og ei raud feilmelding viss noko går gale.

```javascript
async function sendTilbakemelding(navn, melding) {
  try {
    const response = await fetch(
      "https://jsonplaceholder.typicode.com/posts",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          title: navn,
          body: melding,
          userId: 1,
        }),
      }
    );

    if (!response.ok) {
      throw new Error("Feil ved innsending: " + response.status);
    }

    const resultat = await response.json();
    console.log("Lagret med ID:", resultat.id);
    return resultat;

  } catch (error) {
    console.error("Feil:", error.message);
    return null;
  }
}

// Bruk:
sendTilbakemelding("Ola Nordmann", "Flott nettside!").then(resultat => {
  if (resultat) {
    console.log("Tilbakemelding sendt:", resultat);
  }
});
```

POST-førespurnaden krev eit options-objekt med: method sett til "POST", headers med Content-Type for å fortelje tenaren at vi sender JSON, og body med dataene konverterte til JSON-streng med JSON.stringify(). Feilhandteringa returnerer null slik at kallande kode kan sjekke om innsendinga lukkast.

